<?php require 'config.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare("INSERT INTO messages(user_id,sender_role,message) VALUES(?,'admin',?)")->execute([(int)$_POST['user_id'],trim($_POST['message'])]);header('Location: admin_messages.php');exit;}$msgs=$pdo->query("SELECT m.*,u.email FROM messages m JOIN users u ON u.id=m.user_id ORDER BY m.created_at DESC")->fetchAll();$page_title='Customer messages';require 'header.php';?><div class="adminnav"><a href="admin.php">Dashboard</a><a href="admin_products.php">Products & stock</a><a href="admin_orders.php">Orders</a><a href="admin_messages.php">Messages</a><a href="admin_reports.php">Sales reports</a></div><section class="wrap"><h1>Customer messages</h1><?php foreach($msgs as $m):?><div class="stat" style="margin:12px 0"><b><?=e($m['email'])?></b> · <?=e($m['created_at'])?><p><?=e($m['message'])?></p><?php if($m['sender_role']==='customer'):?><form method="post"><input type="hidden" name="user_id" value="<?=$m['user_id']?>"><textarea name="message" required placeholder="Write a reply"></textarea><button>Reply</button></form><?php else:?><small>Admin reply</small><?php endif;?></div><?php endforeach;?></section><?php require 'footer.php';?>
